sys_variable_value.value:
(function execute(inputs, outputs) {

    var users = [];

    var gr = new GlideRecord('x_birl3_clm_demo');

    if (gr.get(inputs.Record)) {

        if (gr.user_1)
            users.push(gr.user_1.toString());

        if (gr.user_2)
            users.push(gr.user_2.toString());

        if (gr.user_3)
            users.push(gr.user_3.toString());

        if (gr.user_4)
            users.push(gr.user_4.toString());

        if (gr.user_5)
            users.push(gr.user_5.toString());
    }

    outputs.users = users;

})(inputs, outputs);

